import{_ as n}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as d,D as s,o as i,c,I as h,w as u,k as t,a as p,R as g,b as m,e as b}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const D=JSON.parse('{"title":"Agent 架构图栏目设计","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-10-16-agent-architecture-diagrams-design.md","filePath":"superpowers/specs/2026-10-16-agent-architecture-diagrams-design.md","lastUpdated":1792148761000}'),A={name:"superpowers/specs/2026-10-16-agent-architecture-diagrams-design.md"},f=t("h1",{id:"agent-架构图栏目设计",tabindex:"-1"},[p("Agent 架构图栏目设计 "),t("a",{class:"header-anchor",href:"#agent-架构图栏目设计","aria-label":'Permalink to "Agent 架构图栏目设计"'},"​")],-1),q=g('<h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>在网站「前沿 &amp; 工作」下新增「Agent 架构图」栏目，用一组按学习顺序排列的结构图帮助读者理解 Agent、RAG、MCP 及其工程化组合。</p><p>栏目是现有 Agent 开发课程的视觉辅助材料，不重复课程正文。读者可以从最小 Agent Loop 开始，逐步看到知识、工具、状态、编排、安全与 Coding Agent Harness 如何组合成完整系统。</p><h2 id="用户与使用方式" tabindex="-1">用户与使用方式 <a class="header-anchor" href="#用户与使用方式" aria-label="Permalink to &quot;用户与使用方式&quot;">​</a></h2><p>面向正在按顺序学习 Agent 开发、需要建立整体结构认知的读者。</p><p>成功标准：</p><ul><li>不阅读长篇说明也能看懂组件边界和数据流。</li><li>每张图只增加有限的新概念，不一次展示全部细节。</li><li>既能顺序浏览，也能从栏目首页直接跳到某个主题。</li><li>桌面端和手机端都能清楚阅读节点文字和箭头关系。</li></ul><h2 id="导航与路径" tabindex="-1">导航与路径 <a class="header-anchor" href="#导航与路径" aria-label="Permalink to &quot;导航与路径&quot;">​</a></h2><ul><li>顶部导航：<code>前沿 &amp; 工作 → Agent 架构图</code></li><li>栏目首页：<code>/categories/agent-diagrams/</code></li><li>图页位于：<code>docs/categories/agent-diagrams/</code></li><li>图页由栏目专用侧边栏按学习顺序组织。</li></ul><h2 id="内容范围" tabindex="-1">内容范围 <a class="header-anchor" href="#内容范围" aria-label="Permalink to &quot;内容范围&quot;">​</a></h2><p>栏目分为四个阶段，共十五张结构图。</p><h3 id="agent-核心" tabindex="-1">Agent 核心 <a class="header-anchor" href="#agent-核心" aria-label="Permalink to &quot;Agent 核心&quot;">​</a></h3><ol><li>LLM、Workflow 与 Agent 的关系</li><li>最小 Agent Loop</li><li>Model、Message 与 Context</li><li>Tool Calling 完整回路</li><li>State、Session 与 Memory</li></ol><h3 id="知识与能力" tabindex="-1">知识与能力 <a class="header-anchor" href="#知识与能力" aria-label="Permalink to &quot;知识与能力&quot;">​</a></h3><ol start="6"><li>RAG 端到端架构</li><li>Chunk、Embedding、Retrieval 与 Rerank</li><li>MCP Host、Client 与 Server</li><li>MCP 工具调用时序</li><li>Skill、Plugin 与 Hook 的关系</li></ol><h3 id="编排与协作" tabindex="-1">编排与协作 <a class="header-anchor" href="#编排与协作" aria-label="Permalink to &quot;编排与协作&quot;">​</a></h3><ol start="11"><li>Workflow、Checkpoint 与恢复</li><li>Human-in-the-Loop 审批</li><li>Multi-Agent Supervisor 与 Handoff</li></ol><h3 id="完整工程" tabindex="-1">完整工程 <a class="header-anchor" href="#完整工程" aria-label="Permalink to &quot;完整工程&quot;">​</a></h3><ol start="14"><li>Guardrail、Trace 与 Evaluation</li><li>Coding Agent / Harness 完整架构总图</li></ol><p>本轮不增加语言基础、API 教程、代码示例、部署教程或模型厂商对比。</p><h2 id="视觉语言" tabindex="-1">视觉语言 <a class="header-anchor" href="#视觉语言" aria-label="Permalink to &quot;视觉语言&quot;">​</a></h2><p>采用已确认的「霓虹回路」方向：深色底面、低饱和发光节点、清晰的回路和结果回填线。</p><p>颜色语义固定：</p><ul><li>主决策与 Agent Loop：蓝色</li><li>知识、RAG 与 Context：绿色</li><li>MCP、Tools 与外部能力：紫色</li><li>审批、安全与停止条件：橙色</li><li>普通数据、基础设施和非激活路径：中性色</li></ul><p>颜色只用于强化分类；节点标签和线型仍要能独立表达含义，不能只靠颜色区分。</p><h2 id="无标题图页" tabindex="-1">无标题图页 <a class="header-anchor" href="#无标题图页" aria-label="Permalink to &quot;无标题图页&quot;">​</a></h2><p>图页不显示大号文章标题、课程导语或正文标题。进入页面后，首屏直接展示结构图。</p><p>允许保留的文字只有：</p><ul><li>左上角轻量序号，例如 <code>02 / 15</code></li><li>小型主题标签，例如 <code>AGENT LOOP</code></li><li>节点名称</li><li>箭头标签</li><li>图例</li><li>选中节点的一句话职责说明</li><li>上一张、下一张导航</li></ul><p>用于 SEO 和 VitePress 路由的 <code>title</code> 仍保留在 frontmatter 中，但不渲染成页面内的大标题。</p><p>栏目首页同样避免传统文章式大标题，直接展示四阶段路线与十五张图的视觉入口。</p><h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><h3 id="栏目首页" tabindex="-1">栏目首页 <a class="header-anchor" href="#栏目首页" aria-label="Permalink to &quot;栏目首页&quot;">​</a></h3><p>首页使用一条分阶段的霓虹学习路线：四个阶段沿主线路展开，每张图显示序号、短名称和微型结构预览。点击进入对应图页。</p><p>首页不显示文章卡片、摘要段落、更新时间或标签墙。</p><h3 id="单图页面" tabindex="-1">单图页面 <a class="header-anchor" href="#单图页面" aria-label="Permalink to &quot;单图页面&quot;">​</a></h3><p>每页只有一个主结构图。结构图占据内容区域的主要空间，不使用额外卡片包裹。</p><p>桌面端优先横向布局；窄屏时按组件关系重新排列为纵向结构，而不是等比例缩小整张 SVG。</p><p>节点支持悬停、键盘聚焦和点击：</p><ul><li>当前节点及其直接路径高亮。</li><li>其他路径降低透明度，但仍保持可见。</li><li>图下方只显示一行当前节点职责说明。</li><li>再次点击空白区域恢复全图。</li></ul><p>本轮不加入缩放画布、拖拽节点、自由编辑、动画粒子或复杂模拟控制。</p><h2 id="组件设计" tabindex="-1">组件设计 <a class="header-anchor" href="#组件设计" aria-label="Permalink to &quot;组件设计&quot;">​</a></h2><p>实现一套可复用的 Vue/SVG 图形系统，十五张图只提供结构数据，不各自复制完整样式和交互。</p><p>核心边界：</p><ul><li><code>AgentDiagramShell</code>：无标题页面骨架、序号、图例、上一张/下一张。</li><li><code>ArchitectureDiagram</code>：渲染节点、分组、连线和选中状态。</li><li><code>DiagramNode</code>：节点外观、可访问标签、键盘和点击交互。</li><li><code>DiagramEdge</code>：请求、结果、状态和控制流四类连线。</li><li><code>diagramCatalog</code>：十五张图的顺序、路由、节点和边定义。</li><li>栏目首页组件：读取同一份 catalog，生成四阶段学习路线。</li></ul><p>图的数据定义至少包含：节点 ID、短标签、类别、职责说明、布局槽位；连线至少包含起点、终点、流类型和可选标签。</p><h2 id="连线语义" tabindex="-1">连线语义 <a class="header-anchor" href="#连线语义" aria-label="Permalink to &quot;连线语义&quot;">​</a></h2><ul><li>实线箭头：请求或主动调用</li><li>反向实线箭头：结果回填</li><li>虚线：状态、事件或观察关系</li><li>带门形节点的路径：审批、校验或停止条件</li></ul><p>每张图必须明确箭头方向，不能用无方向连线表达调用流程。</p><h2 id="技术约束" tabindex="-1">技术约束 <a class="header-anchor" href="#技术约束" aria-label="Permalink to &quot;技术约束&quot;">​</a></h2><ul><li>使用仓库现有 VitePress/Vue 能力和内联 SVG。</li><li>不依赖外部图床、在线绘图服务或运行时 API。</li><li>GitHub Pages 静态构建后必须完全可用。</li><li>适配网站既有浅色/深色主题；默认视觉重点放在深色模式。</li><li>遵循 <code>prefers-reduced-motion</code>；不使用循环动画。</li><li>所有可交互节点使用语义化按钮或等价键盘行为，并提供可读的辅助文本。</li><li>不把 Mermaid 作为最终主要渲染方式，因为本栏目需要统一的霓虹视觉、响应式重排和路径高亮。</li></ul><h2 id="与-agent-课程的关系" tabindex="-1">与 Agent 课程的关系 <a class="header-anchor" href="#与-agent-课程的关系" aria-label="Permalink to &quot;与 Agent 课程的关系&quot;">​</a></h2><p>栏目只负责建立结构认知，不取代 <code>docs/courses/agent/</code>。</p><p>图中的术语、边界和调用方向必须与 Agent 课程保持一致，尤其是：</p><ul><li>Agent 不等于单次 LLM 调用。</li><li>RAG 是 Context 构建能力，不是 Agent Loop 本身。</li><li>MCP 是 Host 与外部能力之间的协议层，不负责模型决策。</li><li>Memory、Session 和 Run State 不可混为同一概念。</li><li>Multi-Agent 不是默认优于单 Agent。</li><li>Guardrail、Sandbox、Approval 和 Trace 属于不同责任边界。</li></ul><h2 id="测试与验收" tabindex="-1">测试与验收 <a class="header-anchor" href="#测试与验收" aria-label="Permalink to &quot;测试与验收&quot;">​</a></h2><p>自动化测试锁定：</p><ul><li>顶部导航存在「Agent 架构图」入口。</li><li>栏目首页和十五个图页路径全部存在。</li><li>catalog 恰好包含十五张图，序号和阶段顺序正确。</li><li>每张图的节点 ID 唯一，连线引用的节点都存在。</li><li>每张图至少包含一个明确方向的主流程。</li><li>图页不渲染大号页面标题。</li><li>节点支持键盘聚焦并具有可访问名称。</li><li>浅色、深色和窄屏布局具有相应样式。</li><li><code>pnpm test</code> 与 <code>pnpm build</code> 通过。</li></ul><p>人工验收重点：</p><ul><li>首屏直接看到结构图，没有难看的大标题占位。</li><li>十五张图的视觉语言一致。</li><li>手机上文字无需缩放即可阅读。</li><li>节点高亮不会隐藏理解主流程所需的信息。</li><li>最后一张总图能准确串联前十四张图，而不是堆叠无关节点。</li></ul><h2 id="非目标" tabindex="-1">非目标 <a class="header-anchor" href="#非目标" aria-label="Permalink to &quot;非目标&quot;">​</a></h2><ul><li>不制作传统长文章。</li><li>不加入代码编辑器或可运行 Agent。</li><li>不提供图形编辑、拖拽编排或导出图片功能。</li><li>不重复 Agent 课程中的 API 速查内容。</li><li>不为视觉效果牺牲箭头方向、文字清晰度或概念准确性。</li></ul>',62);function P(e,_,k,x,C,S){const o=n,r=s("ClientOnly");return i(),c("div",null,[f,h(r,null,{default:u(()=>{var a,l;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((l=e.$frontmatter)==null?void 0:l.showArticleMetadata)??!0)?(i(),m(o,{key:0,article:e.$frontmatter},null,8,["article"])):b("",!0)]}),_:1}),q])}const G=d(A,[["render",P]]);export{D as __pageData,G as default};
